    lines.push(`    title: ${clip(oneLine(row.title), 200)}`);
  lines.push(`    worktree: ${row.worktree} \u2014 ${row.directory || "?"}`);
  if (row.branch)
    lines.push(`    branch: ${row.branch}`);
  if (row.objective)
    lines.push(`    objective: ${clip(oneLine(row.objective), 160)}`);
  if (row.goal)
    lines.push(`    goal: ${clip(oneLine(row.goal), 160)}`);
